async function parseInfrastructureDescription(description) {
  try {
    const response = await fetch('/api/vector-memory', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'parseInfrastructure',
        description: description
      })
    });

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    const result = await response.json();

    if (!result.success) {
      throw new Error(result.error || 'Failed to parse infrastructure description');
    }

    return {
      success: true,
      parsedEntities: result.parsed,
      originalDescription: description,
      entitiesCount: result.parsed ? result.parsed.length : 0,
      message: `Parsed infrastructure description into ${result.parsed ? result.parsed.length : 0} entities`,
      timestamp: new Date().toISOString()
    };
  } catch (error) {
    return {
      success: false,
      error: error.message,
      timestamp: new Date().toISOString()
    };
  }
}
